$payload = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b64)) | ConvertFrom-Json

# ---- Phase 1: check everything in memory (nothing written yet) ----
$byFile = @{}
foreach ($e in $payload.edits) { if (-not $byFile.ContainsKey($e.file)) { $byFile[$e.file] = @() }; $byFile[$e.file] += ,$e }
$newTexts = @{}
$bomFlags = @{}
foreach ($f in $byFile.Keys) {
  $path = Join-Path $root ($f -replace '/', '\')
  if (-not (Test-Path -LiteralPath $path)) { throw "STOP: file not found: $f" }
  $raw = [System.IO.File]::ReadAllBytes($path)
  $bomFlags[$f] = ($raw.Length -ge 3 -and $raw[0] -eq 0xEF -and $raw[1] -eq 0xBB -and $raw[2] -eq 0xBF)
  $text = [System.IO.File]::ReadAllText($path)
  $nl = if ($text.Contains("`r`n")) { "`r`n" } else { "`n" }
  foreach ($e in $byFile[$f]) {
    $old = ($e.old -replace "`r?`n", $nl); $new = ($e.new -replace "`r?`n", $nl)
    $count = ([regex]::Matches($text, [regex]::Escape($old))).Count
    if ($count -ne [int]$e.count) { throw "STOP: in $f expected $($e.count) match(es) but found $count for: $($old.Substring(0,[Math]::Min(70,$old.Length))). Nothing was changed. Tell Claude." }
    $text = $text.Replace($old, $new)
  }
  $newTexts[$f] = $text
}
$newPagePath = Join-Path $root $payload.newfile.path
$newPageText = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($payload.newfile.b64))
if (Test-Path -LiteralPath $newPagePath) {
  $existing = [System.IO.File]::ReadAllText($newPagePath)
  if ($existing -ne $newPageText) { throw "STOP: the new page file already exists with different content: $($payload.newfile.path)" }
}

# ---- Phase 2: back up, then write ----
$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$backup = Join-Path (Split-Path $root -Parent) ("_backup_apply_advance_" + $stamp)
New-Item -ItemType Directory -Path $backup | Out-Null
foreach ($f in $byFile.Keys) {
  $path = Join-Path $root ($f -replace '/', '\')
  $dest = Join-Path $backup ($f -replace '/', '_')
  Copy-Item -LiteralPath $path -Destination $dest
}
foreach ($f in $byFile.Keys) {
  $path = Join-Path $root ($f -replace '/', '\')
  $enc = if ($bomFlags[$f]) { $utf8Bom } else { $utf8 }
  [System.IO.File]::WriteAllText($path, $newTexts[$f], $enc)
  $check = [System.IO.File]::ReadAllText($path)
  if ($check -ne $newTexts[$f]) { throw "STOP: verification failed for $f. Restore from $backup" }
  Write-Host "OK: $f" -ForegroundColor Green
}
$dir = Split-Path $newPagePath -Parent
if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir | Out-Null }
[System.IO.File]::WriteAllText($newPagePath, $newPageText, $utf8)
Write-Host "OK (new): $($payload.newfile.path)" -ForegroundColor Green

Write-Host ""
Write-Host "Changed 4 existing files and added 1 new page. Nothing else was touched." -ForegroundColor Cyan
Write-Host "Backups: $backup" -ForegroundColor Cyan
